import 'package:bloc/bloc.dart';import 'package:meta/meta.dart';import '../../data/entities/product_details.dart';import 'package:zan/Features/client/App/ProductsDetails/domain/UseCase/get_details_product.dart';class ProductDetailsCubit extends Cubit<ProductDetailsState> {  ProductDetailsCubit(this.getDetailsProduct) : super(ProductDetailsState());  final GetDetailsProduct getDetailsProduct;  void changeIndex(int index) {    emit(state.copyWith(index: index));  }  Future<void> getProductDetails({required int id}) async {    emit(ProductDetailsState.loading());    final response = await getDetailsProduct.call(id: id);    response.fold(      (failure) {        emit(ProductDetailsState.error(failure.errMessage));      },      (data) {        emit(ProductDetailsState.success(data));      },    );  }}enum ProductDetailsStatus {  initial,  loading,  success,  error,}@immutableclass ProductDetailsState {  final ProductDetailsStatus status;  final ProductDetailsEntities? product;  final String? errorMessage;  final int? index;  const ProductDetailsState({    this.status = ProductDetailsStatus.initial,    this.product,    this.errorMessage,    this.index = 0,  });  factory ProductDetailsState.loading() =>      const ProductDetailsState(status: ProductDetailsStatus.loading);  factory ProductDetailsState.success(ProductDetailsEntities product) =>      ProductDetailsState(        status: ProductDetailsStatus.success,        product: product,      );  factory ProductDetailsState.error(String message) => ProductDetailsState(        status: ProductDetailsStatus.error,        errorMessage: message,      );  // Helper getters for easy state checking  bool get isInitial => status == ProductDetailsStatus.initial;  bool get isLoading => status == ProductDetailsStatus.loading;  bool get isSuccess => status == ProductDetailsStatus.success;  bool get isError => status == ProductDetailsStatus.error;  // @override  // bool operator ==(Object other) {  //   if (identical(this, other)) return true;  //   return other is ProductDetailsState &&  //       other.status == status &&  //       other.product == product &&  //       other.errorMessage == errorMessage;  // }  //  // @override  // int get hashCode =>  //     status.hashCode ^  //     (product?.hashCode ?? 0) ^  //     (errorMessage?.hashCode ?? 0);  // Create a copy with some changes (immutability pattern)  ProductDetailsState copyWith({    ProductDetailsStatus? status,    ProductDetailsEntities? product,    String? errorMessage,    bool clearProduct = false,    bool clearError = false,    int? index,  }) {    return ProductDetailsState(      status: status ?? this.status,      product: clearProduct ? null : product ?? this.product,      errorMessage: clearError ? null : errorMessage ?? this.errorMessage,      index: index ?? this.index,    );  }}